/**
 * Gap-analysis G1/G2: the linear-chained hash table records its duplicate-chain statistics at build time (chain-length
 * per bucket, max, mean) and lets a probe consume a chain <em>handle's count</em> instead of walking the chain — the
 * first escape of chain structure out of the flat probe loop. The payload-free counted mode is the post-build
 * representation revision: with duplicate keys and no payload slots every chain element would merge an identical output
 * row, so the probe multiplies instead of chasing {@code next[]} pointers.
 */
@Timeout(180)
@ResourceLock(Resources.SYSTEM_PROPERTIES)
public class LmdbNativeHashJoinChainStatsTest {

	private static final String EX = "urn:hash-chain:";
	private static final String P = EX + "p";
	private static final String Q = EX + "q";
	private static final String C = EX + "c";
	private static final String RAW_P_QUERY = "SELECT ?a ?s WHERE { ?a <" + P + "> ?s }";
	private static final String RAW_Q_QUERY = "SELECT ?s WHERE { ?s <" + Q + "> <" + C + "> }";
	private static final String JOIN_QUERY = "SELECT ?a ?s WHERE { ?a <" + P + "> ?s . ?s <" + Q
			+ "> <" + C + "> }";
	private static final Map<String, String> SEMANTIC_HASH_SETTINGS = Map.of(
			LmdbNativeMergeJoin.ENABLED_PROPERTY, "false",
			LmdbNativeLeapfrogJoin.ENABLED_PROPERTY, "false",
			LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "false",
			LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "false",
			LmdbNativeAdaptiveFilterPlacement.ENABLED_PROPERTY, "false",
			"rdf4j.lmdb.factorizedRows.enabled", "false",
			"rdf4j.lmdb.packedFtree.enabled", "false",
			"rdf4j.lmdb.parallel.enabled", "false");

	@Test
	public void buildTimeChainStatisticsTrackDuplicates() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 1);
		int[] keySlots = { 0 };
		int[] payloadSlots = { 1 };

		table.add(new long[] { 100, 1 }, keySlots, payloadSlots);
		table.add(new long[] { 100, 2 }, keySlots, payloadSlots);
		table.add(new long[] { 100, 3 }, keySlots, payloadSlots);
		table.add(new long[] { 200, 4 }, keySlots, payloadSlots);

		assertThat(table.distinctKeys).isEqualTo(2);
		assertThat(table.uniqueKeys).isFalse();
		assertThat(table.maxChainLength()).as("the hot key's chain length").isEqualTo(3);
		assertThat(table.meanChainLength()).as("4 payload rows over 2 distinct keys").isEqualTo(2D);
	}

	/** The per-bucket counts must survive the rehash that bucket growth performs. */
	@Test
	public void chainStatisticsSurviveBucketGrowth() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 0);
		int[] keySlots = { 0 };
		int[] payloadSlots = {};

		for (int i = 0; i < 3; i++) {
			table.add(new long[] { 7 }, keySlots, payloadSlots);
		}
		// push past the 32-bucket load factor so growBuckets() rehashes at least once
		for (long key = 100; key < 160; key++) {
			table.add(new long[] { key }, keySlots, payloadSlots);
		}

		assertThat(table.distinctKeys).isEqualTo(61);
		assertThat(table.maxChainLength()).as("the hot chain's length survives rehashing").isEqualTo(3);
		assertThat(table.meanChainLength()).isEqualTo(63D / 61D);
	}

	/** The chain handle's count is resolvable straight from a prepared probe, without walking the chain. */
	@Test
	public void countedChainLookupResolvesWithoutWalkingTheChain() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 0);
		int[] keySlots = { 0 };
		int[] payloadSlots = {};
		table.add(new long[] { 42 }, keySlots, payloadSlots);
		table.add(new long[] { 42 }, keySlots, payloadSlots);
		table.add(new long[] { 99 }, keySlots, payloadSlots);

		NativeBatch probe = new NativeBatch(1, 4);
		probe.set(0, 0, 42);
		probe.set(0, 1, 99);
		probe.set(0, 2, 7);
		probe.finishRows(3);
		long[] hashState = new long[4];
		int[] hashes = new int[4];
		int[] buckets = new int[4];
		int[] heads = new int[4];
		table.hashBatch(probe, probe.selection, 3, keySlots, hashState, hashes);
		table.headBatch(hashes, 3, buckets, heads);

		assertThat(table.lookupPreparedChainCount(probe, 0, keySlots, hashes[0], buckets[0]))
				.as("duplicate key resolves its chain count")
				.isEqualTo(2);
		assertThat(table.lookupPreparedChainCount(probe, 1, keySlots, hashes[1], buckets[1]))
				.as("singleton key resolves count 1")
				.isEqualTo(1);
		assertThat(table.lookupPreparedChainCount(probe, 2, keySlots, hashes[2], buckets[2]))
				.as("missing key resolves count 0")
				.isEqualTo(0);
	}

	@Test
	public void payloadFreeBuildMultiplicityAcrossContextsMatchesIndependentOracle(@TempDir Path dataRoot)
			throws Exception {
		try (IndependentSparqlOracle oracle = IndependentSparqlOracle.builder(dataRoot)
				.load(LmdbNativeHashJoinChainStatsTest::loadMultiplicityFixture)
				.build()) {
			Map<Arm, EvaluationResult> rawP = oracle.assertEquivalent(RAW_P_QUERY, ResultOrder.UNORDERED);
			assertEveryArmHasRows(rawP, 4_200);

			Map<Arm, EvaluationResult> rawQ = oracle.assertEquivalent(RAW_Q_QUERY, ResultOrder.UNORDERED);
			for (EvaluationResult result : rawQ.values()) {
				assertThat(result.rows()).as("raw q rows in %s", result.arm()).hasSize(1_000);
				assertThat(result.multiset()).as("500 q keys of degree two in %s", result.arm()).hasSize(500);
				assertThat(result.multiset().values())
						.as("every q key occurs in both named contexts in %s", result.arm())
						.allMatch(count -> count == 2L);
			}

			assertPayloadFreeTableBoundary();

			Map<Arm, EvaluationResult> defaultJoined = oracle.evaluateAll(JOIN_QUERY);

			Map<String, String> previousSettings = applySemanticHashSettings();
			Map<Arm, EvaluationResult> semanticHashJoined;
			long builds;
			long countedProbes;
			try {
				long buildsBefore = LmdbNativeHashJoin.BUILDS.get();
				long countedProbesBefore = LmdbNativeHashJoin.COUNTED_CHAIN_PROBES.get();
				semanticHashJoined = oracle.evaluateAll(JOIN_QUERY);
				builds = LmdbNativeHashJoin.BUILDS.get() - buildsBefore;
				countedProbes = LmdbNativeHashJoin.COUNTED_CHAIN_PROBES.get() - countedProbesBefore;
			} finally {
				restoreSettings(previousSettings);
			}

			assertAll("default and semantic native hash phases",
					() -> assertExactJoinedResults("untouched production defaults", defaultJoined),
					() -> assertThat(builds)
							.as("semantic-hash phase selected the native hash-join route")
							.isPositive(),
					() -> assertThat(countedProbes)
							.as("semantic-hash phase used q as payload-free build and all p rows as probes")
							.isEqualTo(4_200),
					() -> assertExactJoinedResults("semantic native hash isolation", semanticHashJoined));
		}
	}

	private static void loadMultiplicityFixture(RepositoryConnection connection) {
		ValueFactory vf = connection.getValueFactory();
		IRI p = vf.createIRI(P);
		IRI q = vf.createIRI(Q);
		IRI c = vf.createIRI(C);
		IRI firstGraph = vf.createIRI(EX, "graph-1");
		IRI secondGraph = vf.createIRI(EX, "graph-2");
		for (int index = 0; index < 4_200; index++) {
			connection.add(vf.createIRI(EX, "a" + index), p, vf.createIRI(EX, "s" + index % 500));
		}
		for (int key = 0; key < 500; key++) {
			IRI subject = vf.createIRI(EX, "s" + key);
			connection.add(subject, q, c, firstGraph);
			connection.add(subject, q, c, secondGraph);
		}
	}

	private static void assertEveryArmHasRows(Map<Arm, EvaluationResult> results, int expectedRows) {
		for (EvaluationResult result : results.values()) {
			assertThat(result.rows()).as("raw rows in %s", result.arm()).hasSize(expectedRows);
		}
	}

	private static void assertExactJoinedResults(String phase, Map<Arm, EvaluationResult> joined) {
		EvaluationResult expected = joined.get(Arm.MEMORY_STANDARD);
		assertThat(expected.failure()).as("%s MemoryStore join evaluation", phase).isNull();
		assertThat(expected.rows()).as("%s MemoryStore rows", phase).hasSize(8_400);
		assertThat(expected.multiset()).as("%s MemoryStore bindings", phase).hasSize(4_200);
		assertThat(expected.multiset().values())
				.as("%s MemoryStore multiplicity", phase)
				.allMatch(count -> count == 2L);
		for (EvaluationResult result : joined.values()) {
			assertThat(result.failure()).as("%s join evaluation in %s", phase, result.arm()).isNull();
			assertThat(result.resultBindingNames())
					.as("%s join binding domain in %s", phase, result.arm())
					.containsExactlyElementsOf(expected.resultBindingNames());
			assertThat(result.rows()).as("%s final joined rows in %s", phase, result.arm()).hasSize(8_400);
			assertThat(result.multiset())
					.as("%s final joined multiset in %s", phase, result.arm())
					.isEqualTo(expected.multiset());
		}
	}

	private static void assertPayloadFreeTableBoundary() {
		PrimitiveHashJoinTable table = new PrimitiveHashJoinTable(1, 0);
		int[] keySlots = { 0 };
		int[] payloadSlots = {};
		for (long key = 1; key <= 500; key++) {
			table.add(new long[] { key }, keySlots, payloadSlots);
			table.add(new long[] { key }, keySlots, payloadSlots);
		}

		assertThat(table.payloadWidth).isZero();
		assertThat(table.payloadCount).as("build rows").isEqualTo(1_000);
		assertThat(table.distinctKeys).as("build keys").isEqualTo(500);
		assertThat(table.maxChainLength()).isEqualTo(2);
		assertThat(table.meanChainLength()).isEqualTo(2D);
	}

	private static Map<String, String> applySemanticHashSettings() {
		Map<String, String> previous = new LinkedHashMap<>();
		SEMANTIC_HASH_SETTINGS
				.forEach((property, value) -> previous.put(property, System.setProperty(property, value)));
		return previous;
	}

	private static void restoreSettings(Map<String, String> previous) {
		previous.forEach((property, value) -> {
			if (value == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, value);
			}
		});
	}
}
